import sys
from collections import defaultdict

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    t = int(input[index])
    index += 1
    results = []
    for _ in range(t):
        n = int(input[index])
        m = int(input[index + 1])
        index += 2
        sets = []
        for _ in range(m):
            vi = int(input[index])
            set_contents = list(map(int, input[index + 1:index + 1 + vi]))
            sets.append(set_contents)
            index += 1 + vi
        graph = defaultdict(list)
        for i in range(n):
            for j in range(i + 1, n):
                in_common = False
                for s in sets:
                    if i in s and j in s:
                        in_common = True
                        break
                if not in_common:
                    graph[i].append(j)
                    graph[j].append(i)
        visited = [False] * n
        def dfs(node, color):
            stack = [(node, color)]
            while stack:
                node, color = stack.pop()
                if visited[node]:
                    continue
                visited[node] = True
                colors[node] = color
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        stack.append((neighbor, 1 - color))
        colors = [-1] * n
        for i in range(n):
            if not visited[i]:
                dfs(i, 0)
        results.append(max(colors) + 1)
    for result in results:
        print(result)

main()
